  add('o_cone', '锥形交通路标', OT, '用于施工、事故现场等临时分隔车道或封闭车道（锥桶）。驾驶要点：不得碾压、穿越锥桶，按其形成的通道减速通过。', () => P('M44 10H56L74 82H26Z', OR) + P('M40.5 26H59.5L63 40H37Z', WH) + P('M35 50H65L68.5 64H31.5Z', WH) + R(14, 82, 72, 8, K, 3));
