  add('mk_edge', '车行道边缘线', MK, '白色实线表示车行道边缘，禁止机动车越线；白色虚线表示允许车辆越线（如出入口、路边停车）。', () => ROAD(VL(12) + VL(88, MW, '12 10') + VL(50, MY, '', 3) + LA(70, 60, .26) + LA(30, 60, .26, 's', 180)));
