  add('mk_turn_wait', '左转弯待转区', MK, '路口内两条白色虚线及“左弯待转区”字样。直行绿灯亮时左转车可进入待转区等候，左转绿灯亮后通行；左转红灯且直行红灯时不得进入。驾驶要点：待转区内不得停车过久或倒车。', () => ROAD(`<path d="M50 74V100" stroke="${MY}" stroke-width="3"/><path d="M72 74V100" stroke="${MW}" stroke-width="2.5"/>` + HL(74, MW, '', 4, 51, 94) + `<path d="M52 74Q50 46 26 32M72 74Q70 38 40 20" stroke="${MW}" stroke-width="2.5" stroke-dasharray="6 5" fill="none"/>` + T(52, 50, 8, '左弯待转区', MW, CJK, ' transform="rotate(-50 52 50)"') + LA(61, 88, .16, 'l')));
  add('mk_diversion', '导流线', MK, '白色V形或斜纹线，表示车辆须按规定路线行驶，不得压线或越线行驶。驾驶要点：不得在导流线内行驶、停车，路口错过时不要压导流线变道。', () => ROAD(EDGE + `<path d="M38 100L50 24L62 100" stroke="${MW}" stroke-width="3" fill="none"/>` + [40, 52, 64, 76, 88].map(y => { const d = (y - 24) / 76 * 12; return `<path d="M${50 - d} ${y}L50 ${y - 9}L${50 + d} ${y}" stroke="${MW}" stroke-width="2.5" fill="none"/>`; }).join('') + LA(22, 52, .26) + LA(78, 52, .26, 'kr')));
