  add('mk_variable_lane', '可变导向车道线', MK, '车道两侧为白色折线（锯齿线），表示车道导向随时段可变，以上方可变导向标志为准。驾驶要点：进入前观察可变指示标志。', () => ROAD(EDGE + `<path d="M34 0L40 8L34 16L40 24L34 32L40 40L34 48L40 56L34 64L40 72L34 80L40 88L34 96M66 0L60 8L66 16L60 24L66 32L60 40L66 48L60 56L66 64L60 72L66 80L60 88L66 96" stroke="${MW}" stroke-width="2.5" fill="none"/>` + LA(50, 50, .26, 'sl')));
  add('mk_tidal', '潮汐车道线', MK, '双黄虚线，表示该车道为潮汐车道，行驶方向随时段变化。驾驶要点：严格依照车道信号灯指示行驶。', () => ROAD(EDGE + VL(34, MY, '12 8', 2.5) + VL(39, MY, '12 8', 2.5) + VL(61, MY, '12 8', 2.5) + VL(66, MY, '12 8', 2.5) + LA(50, 50, .24) + LA(20, 50, .24, 's', 180) + LA(80, 50, .24)));
