  dadd('high_beam', '远光灯', 'blue', '远光灯开启时点亮（蓝色）。在无路灯、照明不良的道路使用；会车、跟车、照明良好路段应改用近光灯。', c => lampR(c) + S('M14 34H44M14 44H44M14 54H44M14 64H44', c, 5));
  dadd('low_beam', '近光灯', 'green', '近光灯开启时点亮。夜间、隧道、雨雾天及会车、跟车时使用。', c => lampR(c) + S('M44 34L16 42M44 44L16 52M44 54L16 62M44 64L16 72', c, 5));
  dadd('fog_front', '前雾灯', 'green', '前雾灯开启时点亮。雾、雨、雪等低能见度天气使用，配合近光灯和示廓灯。', c => lampR(c) + S('M44 34L18 40M44 46L18 52M44 58L18 64', c, 5) + S('M32 26Q26 34 32 42Q38 50 32 58Q26 66 32 74', c, 4));
